UPDATE TB_EEP_PARTNER_M SET
	  PARTNER_NM = #{PARTNER_NM}, BIZ_NO = NULLIF(#{BIZ_NO}, ''), CEO_NM = #{CEO_NM}, OPEN_DT = #{OPEN_DT}, ADDR = #{ADDR}, BIZ_TYPE = #{BIZ_TYPE}, BIZ_ITEM = #{BIZ_ITEM}
	, SALE_YN = #{SALE_YN}, BUY_YN = #{BUY_YN}, USE_YN = #{USE_YN}, MGR_NM = #{MGR_NM}, MGR_POS = #{MGR_POS}, MGR_TEL = #{MGR_TEL}, MGR_HP = #{MGR_HP}, MGR_EMAIL = #{MGR_EMAIL}, TAX_EMAIL = #{TAX_EMAIL}
	, BANK_NM = #{BANK_NM}, ACCOUNT_NO = #{ACCOUNT_NO}, ACCOUNT_HOLDER = #{ACCOUNT_HOLDER}
	, FILE_NM = #{FILE_NM}, FILE_TYPE = #{FILE_TYPE}, FILE_DATA = #{FILE_DATA,jdbcType=BLOB}
	, FILE_NM = NULL, FILE_TYPE = NULL, FILE_DATA = NULL
	, UPDT_EMPLY_ID = #{UPDT_EMPLY_ID}, UPDT_DT = NOW()
WHERE PARTNER_SQ = #{PARTNER_SQ}

UPDATE TB_EEP_DEPLOY_R SET
	  EMP_TYPE_CD = #{EMP_TYPE_CD}, SALE_PARTNER_SQ = NULLIF(#{SALE_PARTNER_SQ}, ''), BUY_PARTNER_SQ = NULLIF(#{BUY_PARTNER_SQ}, ''), CLIENT_NM = #{CLIENT_NM}, PRJ_NM = #{PRJ_NM}, WORK_AREA = #{WORK_AREA}, GRADE_CD = #{GRADE_CD}
	, START_DT = #{START_DT}, END_DT = NULLIF(#{END_DT}, ''), PROB_END_DT = NULLIF(#{PROB_END_DT}, ''), MEMO = #{MEMO}
	, SALE_PRICE = #{SALE_PRICE}, COST_PRICE = #{COST_PRICE}
	, UPDT_EMPLY_ID = #{UPDT_EMPLY_ID}, UPDT_DT = NOW()
WHERE DEPLOY_SQ = #{DEPLOY_SQ}

UPDATE TB_EEP_DEPLOY_R SET END_DT = #{END_DT}
	, SALE_PRICE = #{SALE_PRICE}
	, COST_PRICE = #{COST_PRICE}
	, MEMO = CONCAT(IFNULL(CONCAT(MEMO, '\n'), ''), #{MEMO})
	, UPDT_EMPLY_ID = #{UPDT_EMPLY_ID}, UPDT_DT = NOW()
WHERE DEPLOY_SQ = #{DEPLOY_SQ} AND START_DT <= #{END_DT}

UPDATE TB_EEP_PAYROLL_M SET
	  NP_AMT = #{NP_AMT}, HI_AMT = #{HI_AMT}, LTC_AMT = #{LTC_AMT}, EI_AMT = #{EI_AMT}, ACC_AMT = #{ACC_AMT}, IT_AMT = #{IT_AMT}, LIT_AMT = #{LIT_AMT}
	, NP_SETTLE = #{NP_SETTLE}, HI_SETTLE = #{HI_SETTLE}, EI_SETTLE = #{EI_SETTLE}, LTC_SETTLE = #{LTC_SETTLE}, MUTUAL_AMT = #{MUTUAL_AMT}, ETC_DED = #{ETC_DED}
	, LEDGER_PAY = #{LEDGER_PAY}, UPDT_EMPLY_ID = #{UPDT_EMPLY_ID}, UPDT_DT = NOW()
WHERE PAY_YM = #{YM} AND STAFF_SQ = #{STAFF_SQ}

mapper.select:
SELECT DEPLOY_SQ, STAFF_SQ, EMP_TYPE_CD, SALE_PARTNER_SQ, BUY_PARTNER_SQ, CLIENT_NM, PRJ_NM, WORK_AREA, GRADE_CD
	, START_DT, END_DT, PROB_END_DT, SALE_PRICE, COST_PRICE, MEMO, CLIENT_DIRECT_CD, CLIENT_DIRECT_AMT
FROM TB_EEP_DEPLOY_R WHERE DEPLOY_SQ = #{DEPLOY_SQ}
